"""Registry root and index schema regression tests (fixtures generated by xila-package)."""

import copy
import json
import unittest
from pathlib import Path

from jsonschema import Draft202012Validator
from referencing import Registry, Resource

ROOT = Path(__file__).resolve().parents[1]


def load(name):
    return json.loads((ROOT / name).read_text(encoding="utf-8"))


ROOT_VALIDATOR = Draft202012Validator(load("schemas/registry-root.schema.json"))
INDEX_VALIDATOR = Draft202012Validator(load("schemas/registry-index.schema.json"))
REPOSITORY_VALIDATOR = Draft202012Validator(load("schemas/repository.schema.json"))
ORIGIN_VALIDATOR = Draft202012Validator(load("schemas/package-origin.schema.json"))
ORIGIN_SCHEMA = load("schemas/package-origin.schema.json")
TRANSACTION_VALIDATOR = Draft202012Validator(
    load("schemas/package-transaction.schema.json"),
    registry=Registry().with_resource(ORIGIN_SCHEMA["$id"], Resource.from_contents(ORIGIN_SCHEMA)),
)
ROOT_FIXTURE = load("tests/fixtures/registry-root.json")
REPOSITORY_FIXTURE = load("tests/fixtures/repository.json")
ORIGIN_FIXTURE = load("tests/fixtures/package-origin.json")
INDEX_FIXTURE = load("tests/fixtures/registry-index.json")
TRANSACTION_FIXTURE = load("tests/fixtures/package-transaction.json")


class RegistryTrustSchemaTests(unittest.TestCase):
    def test_accepts_generated_documents(self):
        for validator in (ROOT_VALIDATOR, INDEX_VALIDATOR):
            Draft202012Validator.check_schema(validator.schema)
        ROOT_VALIDATOR.validate(ROOT_FIXTURE)
        INDEX_VALIDATOR.validate(INDEX_FIXTURE)

    def test_rejects_invalid_roots(self):
        for change in [
            lambda r: r.update(version=0),
            lambda r: r.update(root_keys=[]),
            lambda r: r["repository_keys"][0].update(public_key="AAAA"),
            lambda r: r["root_keys"][0].update(id="Root"),
            lambda r: r.update(extra=True),
        ]:
            broken = copy.deepcopy(ROOT_FIXTURE)
            change(broken)
            self.assertFalse(ROOT_VALIDATOR.is_valid(broken), broken)

    def test_accepts_rotation_files_in_the_index(self):
        index = copy.deepcopy(INDEX_FIXTURE)
        index["files"].append({"path": "rotations/dev/xila/clock/2.json", "sha256": "a" * 64, "size": 200})
        INDEX_VALIDATOR.validate(index)

    def test_rejects_invalid_indexes(self):
        for change in [
            lambda i: i.update(version=0),
            lambda i: i["files"][0].update(path="root.json"),
            lambda i: i["files"][0].update(path="packages/../keys/x.json"),
            lambda i: i["files"][0].update(path="namespaces/example/xila.json"),
            lambda i: i["files"][0].update(path="namespaces/../root.json"),
            lambda i: i["files"][0].update(sha256="A" * 64),
            lambda i: i["files"][0].update(size=0),
        ]:
            broken = copy.deepcopy(INDEX_FIXTURE)
            change(broken)
            self.assertFalse(INDEX_VALIDATOR.is_valid(broken), broken)

    def test_repository_and_origin(self):
        for validator in (REPOSITORY_VALIDATOR, ORIGIN_VALIDATOR):
            Draft202012Validator.check_schema(validator.schema)
        REPOSITORY_VALIDATOR.validate(REPOSITORY_FIXTURE)
        ORIGIN_VALIDATOR.validate(ORIGIN_FIXTURE)
        ORIGIN_VALIDATOR.validate(dict(ORIGIN_FIXTURE, repository=None))
        for key, value in [
            ("name", "Xila"),
            ("url", "http://registry.xila.dev"),
            ("url", "https://registry.xila.dev/"),
            ("root_key", "AAAA"),
            ("index_version", -1),
        ]:
            with self.subTest(key=key, value=value):
                self.assertFalse(REPOSITORY_VALIDATOR.is_valid(dict(REPOSITORY_FIXTURE, **{key: value})))
        self.assertFalse(ORIGIN_VALIDATOR.is_valid(dict(ORIGIN_FIXTURE, archive_sha256="x")))
        self.assertFalse(ORIGIN_VALIDATOR.is_valid(dict(ORIGIN_FIXTURE, package_key=None)))

    def test_rotation(self):
        schema = load("schemas/registry-rotation.schema.json")
        Draft202012Validator.check_schema(schema)
        validator = Draft202012Validator(schema)
        rotation = load("tests/fixtures/registry-rotation.json")
        validator.validate(rotation)
        for field, value in [
            ("generation", 1),
            ("generation", 34),
            ("name", "xila.clock"),
            ("previous_key", "AAAA"),
            ("new_key", "AAAA"),
        ]:
            self.assertFalse(validator.is_valid(dict(rotation, **{field: value})))

    def test_transaction(self):
        Draft202012Validator.check_schema(TRANSACTION_VALIDATOR.schema)
        TRANSACTION_VALIDATOR.validate(TRANSACTION_FIXTURE)
        TRANSACTION_VALIDATOR.validate(
            dict(TRANSACTION_FIXTURE, operation="remove", staging=None, previous=".removing-dev.xila.clock", origin=None)
        )
        for key, value in [
            ("operation", "downgrade"),
            ("staging", "../system"),
            ("staging", ".incoming-a/b"),
            ("previous", "/applications/bundles/dev.xila.clock"),
            ("origin", dict(ORIGIN_FIXTURE, archive_sha256="x")),
            ("format_version", 1),
        ]:
            with self.subTest(key=key, value=value):
                self.assertFalse(TRANSACTION_VALIDATOR.is_valid(dict(TRANSACTION_FIXTURE, **{key: value})))


if __name__ == "__main__":
    unittest.main()
